import SelectTokenAndFeeConfirm from '@/components/liquidity/clmm/SelectTokenAndFeeConfirm'
import SelectPoolType from '@/components/pools/createPool/SelectPoolType'
import SelectPool from '@/components/selectPool'
import useSelectPool from '@/hooks/create-pool/useSelectPool'
import { BackButton } from '@cetus/ui-kit'
import { VStack } from '@chakra-ui/react'
import { useNavigate } from 'react-router-dom'
function SelectForLiquidity() {
  const navigate = useNavigate()
  const {
    poolType,
    onContinue,
    baseToken,
    quoteToken,
    setBaseToken,
    setQuoteToken,
    feeTier,
    setFeeTier,
    feeTierList,
    onPoolTypeChange,
    isOpen,
    onClose,
    onConfirm,
    binStep,
    feeOptions,
    handleBinStepChange
  } = useSelectPool()

  const onBack = () => {
    if (poolType === 'dlmm') {
      navigate('/pools?tab=dlmm_pools')
    } else {
      navigate('/pools')
    }
  }

  return (
    <>
      <VStack w="524px" align="flex-start" gap="20px" mt="20px">
        <BackButton text="Pools" onClick={onBack} />
        <SelectPool
          poolType={poolType}
          title="Select pair"
          description="Select the token you want to provide liquidity for."
          onContinue={onContinue}
          baseToken={baseToken}
          onBaseTokenChange={token => setBaseToken(token)}
          quoteToken={quoteToken}
          onQuoteTokenChange={token => setQuoteToken(token)}
          feeTier={feeTier}
          onFeeTierChange={fee => setFeeTier(fee)}
          binStep={binStep}
          binStepList={feeOptions}
          onBinStepChange={handleBinStepChange}
          fromSource="addLiquidity"
          feeTierList={feeTierList}
        >
          <SelectPoolType type={poolType} onChange={onPoolTypeChange} currentStep={1} wrapStyle={{ p: '0' }} />
        </SelectPool>
      </VStack>
      {isOpen && (
        <SelectTokenAndFeeConfirm
          title="This Pool has not been initialized"
          subTitle="Do you want to initialize it?"
          btnText="Initialized Pool"
          isOpen={isOpen}
          onClose={onClose}
          onConfirm={onConfirm}
        />
      )}
    </>
  )
}

export default SelectForLiquidity
